data class Contract(val customer: Party, val supplier: Party, val startDate: LocalDate) {
    init {
        require(customer != supplier) { "customer and supplier must differ" }
        require(startDate >= LocalDate.now()) { "startDate is in the past" }
    }
    companion object {
        fun of(customer: Party, supplier: Party, startDate: LocalDate) = Contract(customer, supplier, startDate)
    }
}
// init runs on every path (delegated secondaries, copy()); invalid input throws
// IllegalArgumentException before any instance exists - never a half-valid object.
